CREATE TABLE metadata_config_heads (tenant_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,version BIGINT UNSIGNED NOT NULL DEFAULT 1,draft_version BIGINT UNSIGNED NULL,published_version BIGINT UNSIGNED NULL,updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT fk_metadata_head_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE CASCADE,CONSTRAINT fk_metadata_head_draft FOREIGN KEY(tenant_id,draft_version) REFERENCES metadata_config_versions(tenant_id,version),CONSTRAINT fk_metadata_head_published FOREIGN KEY(tenant_id,published_version) REFERENCES metadata_config_versions(tenant_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
